#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Run from the project root regardless of where the script is invoked.
cd "$(dirname "$0")/.."
ENV_FILE=".env.supabase"   # remembers answers between runs (gitignored)
LOCAL_PORT=8765
LOCAL_URL="http://localhost:${LOCAL_PORT}"
SERVER_PID=""

# copy_file PATH copies a file to the clipboard when possible; otherwise says where to copy it from.
copy_file() {
  local f="$1"
  if   command -v clip.exe >/dev/null 2>&1; then clip.exe < "$f"
  elif command -v wl-copy  >/dev/null 2>&1 && [[ -n "${WAYLAND_DISPLAY:-}" ]]; then wl-copy < "$f"
  elif command -v xclip    >/dev/null 2>&1 && [[ -n "${DISPLAY:-}" ]]; then xclip -selection clipboard < "$f"
  elif command -v pbcopy   >/dev/null 2>&1; then pbcopy < "$f"
  else
    note "Couldn't reach your clipboard from here. Open ${BOLD}$f${RESET}${DIM} in VS Code → Ctrl+A → Ctrl+C."
    return 0
  fi
  printf '  %s✓ copied%s %s to the clipboard\n' "$GREEN" "$RESET" "$f"
}

# key_role KEY prints: publishable | secret | anon | service_role | unknown
key_role() {
  local k="$1" payload
  case "$k" in
    sb_publishable_*) echo publishable; return ;;
    sb_secret_*)      echo secret; return ;;
  esac
  if [[ "$k" == eyJ*.*.* ]]; then
    payload=$(printf '%s' "$k" | cut -d. -f2 | tr '_-' '/+')
    while (( ${#payload} % 4 )); do payload+="="; done
    payload=$(printf '%s' "$payload" | base64 -d 2>/dev/null || true)
    if   [[ "$payload" == *'"role":"service_role"'* ]]; then echo service_role
    elif [[ "$payload" == *'"role":"anon"'* ]];         then echo anon
    else echo unknown; fi
    return
  fi
  echo unknown
}

# rest_status METHOD PATH [BODY] → HTTP status of a call to the project's REST API with the public key.
rest_status() {
  local method="$1" path="$2" body="${3:-}"
  curl -s -o /dev/null -w '%{http_code}' -X "$method" \
    -H "apikey: ${SUPABASE_ANON_KEY}" -H "Content-Type: application/json" \
    ${body:+--data "$body"} "${SUPABASE_URL}${path}" || true   # curl already prints 000 on network failure
}

# ask_email KEY "Prompt" asks until the value looks like an email address.
ask_email() {
  local key="$1" prompt="$2"
  while true; do
    ask "$key" "$prompt"
    [[ "${!key}" =~ ^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$ ]] && return 0
    warn "That doesn't look like an email address."
  done
}

write_app_config() {
  cat > config.js <<EOF
// App configuration — generated by scripts/setup-supabase.sh (safe to edit by hand).
// Safe to commit: the Supabase publishable/anon key is public by design —
// data is protected by Row Level Security policies in the database, not by hiding this key.
// Leave supabaseUrl empty to run in local-only mode (no login, data stays in this browser).
window.APP_CONFIG = {
  // Supabase → Project Settings → API Keys / Data API
  supabaseUrl: "${SUPABASE_URL}",
  supabaseAnonKey: "${SUPABASE_ANON_KEY}",   // publishable/anon key — NEVER the secret/service_role key

  // OAuth providers shown on the login screen. Each must also be enabled in
  // Supabase → Authentication → Sign In / Providers. Supported here: "google", "apple", "github".
  authProviders: ["google"],

  // false = Google only: hides the email-code form (no custom SMTP needed).
  emailLogin: false,

  // false = the email-code form never creates accounts (only used when emailLogin is true).
  allowEmailSignUp: false
};
EOF
  printf '  %s✓ wrote%s config.js\n' "$GREEN" "$RESET"
}

start_local_server() {
  if curl -s -o /dev/null "$LOCAL_URL/"; then
    note "A server is already running on $LOCAL_URL; using it."
    return
  fi
  python3 -m http.server "$LOCAL_PORT" >/dev/null 2>&1 &
  SERVER_PID=$!
  trap '[[ -n "$SERVER_PID" ]] && kill "$SERVER_PID" 2>/dev/null || true' EXIT
  sleep 1
  printf '  %s✓ started%s local server on %s\n' "$GREEN" "$RESET" "$LOCAL_URL"
}

run_wizard() {

TOTAL_STAGES=8

banner "Supabase setup: Google login for 2 users + database"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Create the Supabase project"
say "One free project holds the login system and the database."
open_url "https://supabase.com/dashboard/new"
step "Sign in (or create a Supabase account) and create an organization if asked (Free plan)."
step "New project → Name: quadro-tarefas"
step "Database password: click 'Generate a password' and save it in your password manager."
note "  (The app never uses it; you only need it for direct database access.)"
step "Region: choose ${BOLD}Europe — Central (Frankfurt)${RESET} (EU, close to Portugal)."
step "Click 'Create new project' and wait ~2 minutes until the dashboard is ready."
pause "Press Enter when the project dashboard has finished loading."

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Project URL and public key → config.js"
open_url "https://supabase.com/dashboard/project/_/settings/api-keys"
step "If asked, pick the quadro-tarefas project."
step "Copy the ${BOLD}Publishable key${RESET} (starts sb_publishable_). If you only see legacy keys, copy the ${BOLD}anon public${RESET} one."
warn "Never use the secret / service_role key: it bypasses all security."
while true; do
  ask SUPABASE_ANON_KEY "Paste the publishable (or anon) key:"
  role=$(key_role "$SUPABASE_ANON_KEY")
  case "$role" in
    publishable|anon) break ;;
    secret|service_role) warn "That's a SECRET key. Don't use it anywhere in the app. Copy the publishable/anon key instead." ;;
    *) warn "That doesn't look like a Supabase key. Try again." ;;
  esac
done
step "Now the Project URL: Project Settings → Data API → 'Project URL' (or the 'Connect' button at the top)."
open_url "https://supabase.com/dashboard/project/_/settings/api"
while true; do
  ask SUPABASE_URL "Paste the Project URL (https://xxxx.supabase.co):"
  SUPABASE_URL="${SUPABASE_URL%/}"
  [[ "$SUPABASE_URL" =~ ^https://[a-z0-9]+\.supabase\.co$ ]] && break
  warn "Expected something like https://abcdefghijklmnop.supabase.co"
done
PROJECT_REF="${SUPABASE_URL#https://}"; PROJECT_REF="${PROJECT_REF%%.*}"
write_env SUPABASE_URL "$SUPABASE_URL"
write_env SUPABASE_ANON_KEY "$SUPABASE_ANON_KEY"
write_env SUPABASE_PROJECT_REF "$PROJECT_REF"
write_app_config
code=$(rest_status GET "/auth/v1/settings")
if [[ "$code" == 200 ]]; then printf '  %s✓ connected%s to %s\n' "$GREEN" "$RESET" "$SUPABASE_URL"
else warn "Couldn't reach the project (HTTP $code). Check URL/key; you can re-run this wizard later."; fi
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Create the database tables + security rules"
say "This creates one table for all your items, per-user access rules, and a private file bucket."
copy_file supabase/schema.sql
open_url "https://supabase.com/dashboard/project/${PROJECT_REF}/sql/new"
step "Paste the SQL into the editor and click ${BOLD}Run${RESET}."
step "If it warns about 'destructive operations', that's the drop-if-exists lines; confirm to run."
step "Expected result: 'Success. No rows returned'."
while true; do
  pause "Press Enter after it ran successfully."
  read_code=$(rest_status GET "/rest/v1/records?select=id&limit=1")
  write_code=$(rest_status POST "/rest/v1/records" '{"collection":"tasks","id":"probe","updated_at":0}')
  if [[ "$read_code" =~ ^(200|401|403)$ && "$write_code" =~ ^(401|403)$ ]]; then
    printf '  %s✓ verified%s table exists and anonymous writes are blocked (HTTP %s)\n' "$GREEN" "$RESET" "$write_code"
    break
  fi
  warn "Check failed (read HTTP $read_code, anonymous write HTTP $write_code)."
  note "404 = table not created yet (run the SQL). 201 = SECURITY PROBLEM: re-run the whole schema.sql."
  confirm "Try the check again?" || { SKIPPED+=("Verify schema.sql ran (records table + RLS)"); break; }
done
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Allowed web addresses"
say "Login can only send you back to addresses on this list."
open_url "https://supabase.com/dashboard/project/${PROJECT_REF}/auth/url-configuration"
step "Site URL: ${BOLD}${LOCAL_URL}${RESET}  (change to your real address once it's hosted)"
step "Redirect URLs → Add URL: ${BOLD}${LOCAL_URL}/**${RESET} → Save."
note "When you host it (e.g. GitHub Pages), add https://\<you\>.github.io/\<repo\>/\*\* here too."
pause "Press Enter when saved."

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Google sign-in (only these 2 Google accounts can log in)"
CALLBACK_URL="${SUPABASE_URL}/auth/v1/callback"
say "Two separate accounts: each one only ever sees its own data."
ask_email USER_EMAIL_1 "Google account of user 1:"
ask_email USER_EMAIL_2 "Google account of user 2:"
if [[ "${USER_EMAIL_1,,}" == "${USER_EMAIL_2,,}" ]]; then
  warn "Both emails are the same; that would be one account. Re-run with two different Google accounts."
fi
write_env USER_EMAIL_1 "$USER_EMAIL_1"
write_env USER_EMAIL_2 "$USER_EMAIL_2"
printf '\n'
open_url "https://console.cloud.google.com/projectcreate"
step "Create a Google Cloud project (name: quadro-tarefas). Select it afterwards."
pause "Press Enter when the project is selected."
open_url "https://console.cloud.google.com/auth/overview"
step "Google Auth Platform → ${BOLD}Get started${RESET}: App name 'Quadro de Tarefas', your email as support/contact."
step "Audience: ${BOLD}External${RESET}. Leave the app in ${BOLD}Testing${RESET} (don't publish)."
step "Audience → Test users → Add users: ${BOLD}${USER_EMAIL_1}${RESET} and ${BOLD}${USER_EMAIL_2}${RESET}."
note "  Testing mode = only these test users can sign in. That's your allow-list."
pause "Press Enter when done."
open_url "https://console.cloud.google.com/auth/scopes"
step "Data Access → Add or remove scopes → tick ${BOLD}openid${RESET} (email and profile are already there) → Update → Save."
pause "Press Enter when saved."
open_url "https://console.cloud.google.com/auth/clients/create"
step "Application type: ${BOLD}Web application${RESET}. Name: Supabase."
step "Authorized JavaScript origins → Add: ${BOLD}${LOCAL_URL}${RESET}"
step "Authorized redirect URIs → Add: ${BOLD}${CALLBACK_URL}${RESET}"
step "Create. Keep the dialog with the Client ID and Client secret open."
pause "Press Enter when you see the Client ID and secret."
open_url "https://supabase.com/dashboard/project/${PROJECT_REF}/auth/providers?provider=Google"
step "In Supabase → Google: switch ${BOLD}Enable${RESET} on."
step "Paste the Client ID and Client secret from Google directly here (they're not stored in this project)."
step "Check the Callback URL shown there matches: ${CALLBACK_URL}"
step "Save."
pause "Press Enter when saved."

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Turn off email login"
say "The app only shows Google. Disabling email in Supabase closes that door completely,"
say "so nobody can create an account by calling the API with an email address."
open_url "https://supabase.com/dashboard/project/${PROJECT_REF}/auth/providers"
step "Authentication → Sign In / Providers → ${BOLD}Email${RESET} → switch ${BOLD}Enable Email provider${RESET} off → Save."
step "Make sure ${BOLD}Allow new users to sign up${RESET} is still ${BOLD}on${RESET} for now (the next step creates both accounts)."
pause "Press Enter when saved."

# ── 7 ────────────────────────────────────────────────────────────────────
stage "First login of both users (creates their accounts)"
start_local_server
open_url "$LOCAL_URL"
note "If the page shows the old app, hard-refresh (Ctrl+Shift+R)."
step "Continuar com Google → ${BOLD}${USER_EMAIL_1}${RESET}."
note "  Google shows 'Google hasn't verified this app' (normal in Testing mode) → Continue."
note "  If asked to link this browser's existing data to the account: OK only for the user who owns it."
step "You see the app with ${USER_EMAIL_1} at the top. Add a test task, then ${BOLD}Terminar sessão${RESET}."
step "Continuar com Google → ${BOLD}${USER_EMAIL_2}${RESET} (use 'Use another account' on Google's screen)."
step "User 1's test task must ${BOLD}not${RESET} appear."
if confirm "Did both users sign in, each seeing only their own data?"; then
  printf '  %s✓ both accounts created%s\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Login test failed: check the message under the button, and Supabase → Logs → Auth")
  warn "Common causes: redirect URL missing (stage 4), email not in Google test users or redirect URI mismatch (stage 5)."
fi
open_url "https://supabase.com/dashboard/project/${PROJECT_REF}/auth/users"
step "Check that exactly two users are listed: ${USER_EMAIL_1} and ${USER_EMAIL_2}."
pause

# ── 8 ────────────────────────────────────────────────────────────────────
stage "Lock it down: no new sign-ups"
say "Both accounts exist now, so new sign-ups can be closed."
open_url "https://supabase.com/dashboard/project/${PROJECT_REF}/auth/providers"
step "Turn ${BOLD}off${RESET} 'Allow new users to sign up' → Save."
pause "Press Enter when saved."
step "At ${LOCAL_URL}: Terminar sessão → Continuar com Google → either user."
if ! confirm "Did Google sign-in still work with sign-ups off?"; then
  SKIPPED+=("Google login fails with sign-ups off: check Supabase → Logs → Auth; temporarily re-enable sign-ups if needed")
fi

finish
say "Next: the app has login; syncing data to the database is the next code step."
say "Values saved in $ENV_FILE (gitignored) and config.js (safe to commit)."
printf '\n'
}

run_wizard "$@"; exit
